import Image from "next/image";
import Link from "next/link";
import { notFound } from "next/navigation";
import { MessageCircle } from "lucide-react";
import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { formatINR } from "@/lib/money";
import { formatDate } from "@/lib/utils";
import { PageHeader, Panel } from "@/components/admin/ui";
import { OrderStatusBadge, statusLabel } from "@/components/OrderStatus";
import { PaymentBadge } from "@/components/PaymentBadge";
import { OrderStatusForm, RefundForm } from "@/components/admin/OrderForms";

export default async function AdminOrderDetail({ params }: PageProps<"/admin/orders/[id]">) {
  const { id } = await params;
  const [order, me] = await Promise.all([
    db.order.findUnique({ where: { id }, include: { items: true, events: { orderBy: { createdAt: "desc" } }, user: { select: { name: true, email: true, _count: { select: { orders: true } } } }, coupon: true } }),
    getCurrentUser(),
  ]);
  if (!order) notFound();
  const a = order.shippingAddress as Record<string, string>;
  const wa = `https://wa.me/${a.phone?.replace(/\D/g, "").replace(/^(\d{10})$/, "91$1")}?text=${encodeURIComponent(`Hello ${a.name}, update on your Sun Metals Store order #${order.orderNumber}: `)}`;

  return (
    <>
      <PageHeader
        title={`Order #${order.orderNumber}`}
        description={`Placed ${formatDate(order.createdAt, true)}${order.paidAt ? ` · paid ${formatDate(order.paidAt, true)}` : ""}`}
        actions={
          <>
            <OrderStatusBadge status={order.status} />
            {order.paidAt && <Link href={`/order/${order.orderNumber}/invoice`} target="_blank" className="btn-outline">GST invoice</Link>}
            <a href={wa} target="_blank" rel="noopener noreferrer" className="btn-outline"><MessageCircle className="h-4 w-4" /> WhatsApp customer</a>
          </>
        }
      />
      <div className="grid gap-6 xl:grid-cols-[1fr_340px]">
        <div className="space-y-6">
          <Panel title="Items">
            <ul className="divide-y divide-line">
              {order.items.map((it) => (
                <li key={it.id} className="flex items-center gap-4 py-3 text-sm">
                  <div className="relative h-14 w-14 shrink-0 rounded bg-paper">{it.image && <Image src={it.image} alt="" fill sizes="56px" className="object-contain p-1" />}</div>
                  <div className="flex-1">
                    <p className="font-medium">{it.productId ? <Link href={`/admin/products/${it.productId}`} className="hover:text-maroon">{it.name}</Link> : it.name}</p>
                    <p className="text-xs text-muted">SKU {it.sku} · GST {it.gstRate}%</p>
                    {it.engravingText && <p className="mt-1 inline-block rounded bg-brass-light px-2 py-0.5 text-xs font-semibold text-brass">ENGRAVE: “{it.engravingText}”</p>}
                  </div>
                  <p className="tabular-nums text-muted">{it.quantity} × {formatINR(it.unitPrice)}</p>
                  <p className="w-24 text-right font-semibold tabular-nums">{formatINR(it.unitPrice * it.quantity)}</p>
                </li>
              ))}
            </ul>
            <dl className="ml-auto mt-3 w-64 space-y-1 text-sm">
              <div className="flex justify-between"><dt>Subtotal</dt><dd>{formatINR(order.subtotal)}</dd></div>
              {order.discount > 0 && <div className="flex justify-between text-success"><dt>Coupon {order.coupon?.code}</dt><dd>−{formatINR(order.discount)}</dd></div>}
              <div className="flex justify-between"><dt>Shipping</dt><dd>{formatINR(order.shippingFee)}</dd></div>
              <div className="flex justify-between border-t border-line pt-1 font-semibold"><dt>Total</dt><dd>{formatINR(order.total)}</dd></div>
              <div className="flex justify-between text-xs text-muted"><dt>GST included</dt><dd>{formatINR(order.taxTotal, true)}</dd></div>
            </dl>
          </Panel>
          <Panel title="Timeline">
            <ol className="space-y-3 border-l-2 border-line pl-4 text-sm">
              {order.events.map((e) => (
                <li key={e.id}>
                  <p className="font-medium">{statusLabel(e.status)}</p>
                  {e.note && <p className="text-ink-soft">{e.note}</p>}
                  <p className="text-xs text-muted">{formatDate(e.createdAt, true)}</p>
                </li>
              ))}
            </ol>
          </Panel>
        </div>
        <div className="space-y-6">
          <Panel title="Customer">
            <p className="text-sm font-medium">{a.name}</p>
            <p className="text-sm text-muted">{order.email}<br />{order.phone}</p>
            {order.user && <p className="mt-1 text-xs text-muted">{order.user._count.orders} orders in total</p>}
            <p className="mt-3 text-sm">{a.line1}{a.line2 && `, ${a.line2}`}<br />{a.city}, {a.state} – {a.pincode}</p>
            {order.notes && <p className="mt-3 rounded bg-paper p-2 text-sm">Note: {order.notes}</p>}
          </Panel>
          <Panel title="Payment">
            <div className="text-sm"><PaymentBadge method={order.paymentMethod} details={order.paymentDetails as Record<string, string | number | null> | null} /></div>
            {order.preferEmi && <p className="mt-1 text-xs text-muted">Customer chose “Pay with EMI” at checkout.</p>}
            <p className="mt-2 break-all text-xs text-muted">Razorpay order: {order.razorpayOrderId ?? "—"}<br />Payment: {order.razorpayPaymentId ?? "—"}</p>
          </Panel>
          {order.paidAt && (
            <Panel title="Fulfilment">
              <OrderStatusForm id={order.id} status={order.status} courier={order.courier ?? ""} trackingNumber={order.trackingNumber ?? ""} />
            </Panel>
          )}
          {order.razorpayPaymentId && order.status !== "REFUNDED" && me?.role === "ADMIN" && (
            <Panel title="Refund"><RefundForm id={order.id} total={order.total} /></Panel>
          )}
        </div>
      </div>
    </>
  );
}
